style.css:
@-moz-document domain("thetradeshowcalendar.com") {
/* Body Styling */
  body {
    font-family: 'Roboto', Arial, sans-serif;
    background: linear-gradient(120deg, #1e90ff, #ff69b4);
    color: #fff;
    margin: 0;
    padding: 0;
  }

  /* Header Styling */
  header {
    background: rgba(0, 0, 0, 0.8);
    padding: 20px;
    text-align: center;
    border-bottom: 3px solid #ff69b4;
  }
  header h1 {
    color: #fff;
    font-size: 2.5em;
    letter-spacing: 2px;
  }

  /* Navigation Menu */
  nav {
    background: rgba(0, 0, 0, 0.7);
    padding: 10px 0;
    display: flex;
    justify-content: center;
    gap: 20px;
  }
  nav a {
    color: #ffeb3b;
    font-weight: bold;
    text-decoration: none;
    padding: 10px 20px;
    border-radius: 5px;
    transition: background-color 0.3s ease-in-out;
  }
  nav a:hover {
    background-color: rgba(255, 255, 255, 0.2);
  }

  /* Content Styling */
  .content {
    padding: 20px;
    max-width: 1200px;
    margin: 0 auto;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 15px;
    box-shadow: 0px 5px 15px rgba(0, 0, 0, 0.5);
  }

  /* Table Styling */
  table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
  }
  th, td {
    border: 1px solid rgba(255, 255, 255, 0.3);
    padding: 10px;
    text-align: left;
    color: #fff;
  }
  th {
    background: rgba(255, 105, 180, 0.7);
  }
  tr:nth-child(even) {
    background: rgba(255, 255, 255, 0.1);
  }

  /* Footer Styling */
  footer {
    background: rgba(0, 0, 0, 0.8);
    text-align: center;
    padding: 10px 0;
    margin-top: 20px;
    border-top: 3px solid #1e90ff;
  }
  footer p {
    color: #ffeb3b;
    font-size: 0.9em;
  }

  /* Responsive Design */
  @media (max-width: 768px) {
    header h1 {
      font-size: 2em;
    }
    .content {
      padding: 15px;
    }
    nav a {
      padding: 5px 10px;
    }
  }
}
